const appStoreLink = 'https://apps.apple.com/app/id1382218014?utm_source=pencakewebsite&utm_medium=button';
const playStoreLink = 'https://play.google.com/store/apps/details?id=com.diffathy.bbapp&referrer=utm_source%3Dpencakewebsite%26utm_medium%3Dbutton';
const desktopLink = '/download/mobile/';

const userAgent = navigator.userAgent || navigator.vendor || window.opera;

document.getElementById('downloadMobile').addEventListener('click', function(e) {
  e.preventDefault();

  if (/android/i.test(userAgent)) {
    window.location.href = playStoreLink;
  } else if (/iPad|iPhone|iPod/.test(userAgent) && !window.MSStream) {
    window.location.href = appStoreLink;
  } else {
    window.location.href = desktopLink;
  }
});
